    if ref.tzinfo is None:
        ref = ref.replace(tzinfo=timezone.utc)
    days_ago = max(0.0, (ref - created_at).total_seconds() / 86400.0)
    return math.exp(-math.log(3) / _HALF_LIFE * days_ago)

