            rows = (
                await db.execute(
                    select(
                        Signal.action,
                        Signal.confidence,
                        Signal.outcome_14d,
                        Signal.outcome_pct,
                        Signal.created_at,
                    )
                    .where(Signal.is_sent == True)
                    .where(Signal.action.in_(["BUY", "SELL"]))
                    .where((Signal.outcome_14d.isnot(None)) | (Signal.outcome_pct.isnot(None)))
                    .order_by(Signal.created_at)
                )
            ).all()

