            sub = [s for s in train if s["regime"] == regime]
            if len(sub) < 20:
                log.debug(f"[calibration] {regime}: only {len(sub)} samples — skip")
                continue
            rx = [s["conf"] / 100.0 for s in sub]
            ry = [s["win"] for s in sub]
            rw = [s["weight"] for s in sub]
