            rbins: dict[int, dict] = defaultdict(lambda: {"XXw_winsXX": 0.0, "w_total": 0.0})
            for s in sub:
                b = max(0, min(95, (int(s["conf"]) // _BIN_SIZE) * _BIN_SIZE))
