        if iso_global:
            cal_map["_isotonic"] = iso_global
            log.info(f"[calibration] global isotonic fitted on {len(_X)} samples")

        # ── Regime-specific isotonic ─────────────────────────────────────────
        regime_map: dict[str, dict] = {}
